  --trans-text-color: #D1D1D1;               
  --trans-meta-color: #5E5E5E;              
  --trans-icon-url: url("https://xiuxiu-pro-new.meitudata.com/posters/e37c962355adec7c7c3116b07ba10f0c.png");

