.msg-transfer-card.msg-transfer-success:not(.msg-redpacket-card) .msg-transfer-amount::after,
.msg-transfer-card[class*="success" i]:not(.msg-redpacket-card) .msg-transfer-amount::after,
.msg-transfer-card[class*="receive" i]:not(.msg-redpacket-card) .msg-transfer-amount::after {
