.msg-transfer-card.msg-transfer-rejected:not(.msg-redpacket-card) .msg-transfer-amount,
.msg-transfer-card.msg-transfer-rejected:not(.msg-redpacket-card) .msg-transfer-amount *,
.msg-transfer-card[class*="reject" i]:not(.msg-redpacket-card) .msg-transfer-amount,
.msg-transfer-card[class*="reject" i]:not(.msg-redpacket-card) .msg-transfer-amount * {
  color: var(--transfer-rejected-color) !important;
}
.msg-transfer-card.msg-transfer-rejected:not(.msg-redpacket-card) .msg-transfer-amount::after,
.msg-transfer-card[class*="reject" i]:not(.msg-redpacket-card) .msg-transfer-amount::after {
