  height: 100px !important;
  min-height: 100px !important;
  max-height: 100px !important;
  margin: 0 !important;
  border: none !important;
  border-radius: 0 !important;
  flex: 0 0 100px !important;
  filter: brightness(0.85) contrast(1.05) !important;
}

.msg-loc-footer,
.msg-loc-footer-text,
.msg-loc-dist,
.msg-loc-approx,
.msg-loc-info svg,
.msg-loc-header svg,
.msg-loc-card [class*="arrow"] {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
  opacity: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* ==========================================================================
   11.7 语音/视频通话气泡
   ========================================================================== */

/* 1. 消除拉伸 */
.msg-row:has(.msg-videocall-card),
.msg-bubble:has(.msg-videocall-card),
.msg-content:has(.msg-videocall-card),
.msg-bubble-container:has(.msg-videocall-card) {
  width: -webkit-fit-content !important;
  width: -moz-fit-content !important;
  width: fit-content !important;
  max-width: -webkit-fit-content !important;
  max-width: fit-content !important;
  min-width: 0 !important;
  flex: 0 0 auto !important;
}

/* 2. 气泡外壳 */
.bubble-me-custom:has(.msg-videocall-card) {
  display: inline-flex !important;
  width: max-content !important;
  min-width: 0 !important;
  max-width: max-content !important;
  padding: var(--bubble-me-padding) !important;
  border-radius: var(--bubble-me-radius) !important;
  background-color: var(--bubble-me-bg) !important;
  color: var(--bubble-me-color) !important;
  box-sizing: border-box !important;
  flex: 0 0 auto !important;
}

.bubble-them-custom:has(.msg-videocall-card) {
  display: inline-flex !important;
  width: max-content !important;
  min-width: 0 !important;
  max-width: max-content !important;
  padding: var(--bubble-them-padding) !important;
  border-radius: var(--bubble-them-radius) !important;
  background-color: var(--bubble-them-bg) !important;
  color: var(--bubble-them-color) !important;
  box-sizing: border-box !important;
  flex: 0 0 auto !important;
}

/* 3. 卡片容器 */
.msg-videocall-card {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: flex-start !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;
  gap: 3px !important;
  width: max-content !important;
  min-width: 0 !important;
  max-width: max-content !important;
  min-height: unset !important;
  height: auto !important;
  position: relative !important;
  flex: 0 0 auto !important;
  box-sizing: border-box !important;
}

/* 我方 */
.msg-me .msg-videocall-card {
  flex-direction: row !important;
}
/* 对方 */
.msg-them .msg-videocall-card {
  flex-direction: row-reverse !important;
}

/* 4. 消除箭头 */
.msg-videocall-card .msg-videocall-icon,
.msg-videocall-card [class*="icon" i],
.msg-videocall-card [class*="arrow" i],
.msg-videocall-card [class*="chevron" i],
.msg-videocall-card svg,
.msg-videocall-card img {
  display: none !important;
  width: 0 !important;
  height: 0 !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* 5. 状态与文字 */

/* === 5A. 未接通卡片（已取消、已拒绝） === */
.msg-videocall-card:not(.connected) > * {
  display: none !important;
}

.msg-videocall-card:not(.connected)::before {
  display: inline-block !important;
  font-size: inherit !important;    
  color: inherit !important;
  -webkit-text-fill-color: currentColor !important;
  white-space: nowrap !important;
  flex: 0 0 auto !important;
}

.msg-me .msg-videocall-card:not(.connected)::before {
  content: "已取消" !important;
}
.msg-them .msg-videocall-card:not(.connected)::before {
  content: "已拒絕" !important;
}

/* === 5B. 已接通卡片 === */
.msg-videocall-card.connected::before {
  display: none !important;
}

/* 隐藏第一行 */
.msg-videocall-card.connected > div:not(.msg-videocall-icon):not([class*="icon"]) > *:first-child {
  display: none !important;
}

/* 展开范化文字 */
.msg-videocall-card.connected > div:not(.msg-videocall-icon):not([class*="icon"]) {
  display: inline-flex !important;
  align-items: center !important;
  width: auto !important;
  min-width: 0 !important;
  max-width: max-content !important;
  flex: 0 0 auto !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  font-size: inherit !important;       
}

/* 白名单 */
.msg-videocall-card.connected > div:not(.msg-videocall-icon):not([class*="icon"]) > *:last-child {
  display: inline-block !important;
  font-size: inherit !important;      
  color: inherit !important;
  -webkit-text-fill-color: currentColor !important;
  margin: 0 !important;
  padding: 0 !important;
  white-space: nowrap !important;
  flex: 0 0 auto !important;
}

/* 拼接文字 */
.msg-videocall-card.connected > div:not(.msg-videocall-icon):not([class*="icon"]) > *:last-child::before {
  content: "通話時長 " !important;
  font-size: inherit !important;         
  color: inherit !important;
  -webkit-text-fill-color: currentColor !important;
}

/* 6. 电话图标 */
.msg-videocall-card::after {
  content: "" !important;
  display: inline-block !important;
  width: 17px !important;
  height: 17px !important;
  min-width: 17px !important;
  min-height: 17px !important;
  background-color: currentColor !important;
  -webkit-mask: url("https://i.postimg.cc/HWqjHNmJ/IMG-8085.png") no-repeat center / contain !important;
  mask: url("https://i.postimg.cc/HWqjHNmJ/IMG-8085.png") no-repeat center / contain !important;
  flex: 0 0 auto !important;
}

/* ==========================================================================
   12. 红包卡片与小尖角
   ========================================================================== */
:root {
  --redpacket-card-width: 240px;
  --redpacket-card-height: 88px;
  --redpacket-card-radius: 4px;
  --redpacket-bg: #d59148;
  --redpacket-opened-bg: #a57137;
  --redpacket-opened-text-color: #ce995c;
  --redpacket-title: "恭喜發財，大吉大利";
  --redpacket-tip-done: "已領取";
}

/* 外层容器 */
.msg-bubble-container:has(.msg-redpacket-card) {
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
  width: fit-content !important;
}

/* 卡片本体及未领取底色 */
.msg-redpacket-card,
.msg-redpacket-card.is-unopened {
  width: var(--redpacket-card-width) !important;
  height: var(--redpacket-card-height) !important;
  box-sizing: border-box !important;
  border-radius: var(--redpacket-card-radius) !important;
  position: relative !important;
  overflow: visible !important;
  border: none !important;
  background: var(--redpacket-bg) !important;
}

/* 清除干扰项 */
.msg-redpacket-card,
.msg-redpacket-card * {
  font-size: 0 !important;
  color: transparent !important;
  line-height: 0 !important;
  border: none !important;
  box-shadow: none !important;
}
.msg-redpacket-card * {
  background: transparent !important;
}
.msg-redpacket-card svg,
.msg-redpacket-card hr,
.msg-redpacket-card [class*="line" i],
.msg-redpacket-card .msg-transfer-amount,
.msg-redpacket-emoji {
  display: none !important;
}

/* 红包图标 */
.msg-redpacket-card::before {
  content: "" !important;
  position: absolute !important;
  left: 16px !important;
  top: 15px !important;
  width: 32px !important;
  height: 38px !important;
  background: url("https://i.postimg.cc/8PxnHChW/IMG-7318.png") no-repeat center / contain !important;
  -webkit-mask: none !important;
  mask: none !important;
  border-radius: 0 !important;
  z-index: 2 !important;
}

/* 底部文字 */
.msg-redpacket-card::after {
  content: "利是" !important;
  position: absolute !important;
  left: 14px !important;
  bottom: 8px !important;
  font-size: 9.5px !important;
  color: rgba(255, 255, 255, 0.75) !important;
  line-height: 1 !important;
  font-family: -apple-system, sans-serif !important;
  z-index: 2 !important;
}

/* 标题样式 */
.msg-redpacket-card > :first-child {
  position: absolute !important;
  left: 32px !important;
  top: 0 !important;
  width: calc(100% - 36px) !important;
  height: 100% !important;
  display: flex !important;
  align-items: center !important;
  z-index: 10 !important;
}
.msg-redpacket-card > :first-child::before {
  content: var(--redpacket-title) !important;
  font-size: 15.5px !important;
  font-weight: 500 !important;
  color: #ffffff !important;
  line-height: 1.2 !important;
  white-space: nowrap !important;
  visibility: visible !important;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif !important;
  display: block !important;
}

/* 已拆封卡片底色与图标 */
.msg-redpacket-card.is-opened,
.msg-redpacket-card[class*="receive" i],
.msg-redpacket-card[class*="success" i] {
  background: var(--redpacket-opened-bg) !important;
}
.msg-redpacket-card.is-opened::before,
.msg-redpacket-card[class*="receive" i]::before,
.msg-redpacket-card[class*="success" i]::before {
  background: url("https://i.postimg.cc/pXRLTQYx/IMG-9919.png") no-repeat center / contain !important;
}

/* 已领取底部文字颜色 */
.msg-redpacket-card:is(.is-opened, [class*="receive" i], [class*="success" i])::after {
  color: var(--redpacket-opened-text-color) !important;
}

/* 已领取标题文字颜色 */
.msg-redpacket-card:is(.is-opened, [class*="receive" i], [class*="success" i]) > :first-child::before {
  color: var(--redpacket-opened-text-color) !important;
}

/* 已领取提示文字定位与颜色 */
.msg-redpacket-card:is(.is-opened, [class*="receive" i], [class*="success" i]) > :first-child::after {
  content: var(--redpacket-tip-done) !important;
  position: absolute !important;
  left: 32px !important;
  top: calc(50% + 0px) !important;
  font-size: 11.5px !important;
  font-weight: 400 !important;
  color: var(--redpacket-opened-text-color) !important;
  line-height: 1.2 !important;
  white-space: nowrap !important;
  visibility: visible !important;
  font-family: -apple-system, BlinkMacSystemFont, sans-serif !important;
}

/* 尖角基础 */
.bubble-me-custom:has(.msg-redpacket-card)::before,
.bubble-them-custom:has(.msg-redpacket-card)::before {
  display: block !important;
  content: "" !important;
  width: var(--tail-width) !important;
  height: var(--tail-height) !important;
  z-index: 1 !important;
  background: var(--redpacket-bg) !important;
}

/* 对方尖角未领取 */
.bubble-them-custom:has(.msg-redpacket-card)::before {
  top: 18.5px !important;
  left: -9px !important;
  transform: translateY(-50%) translate(var(--tail-them-x), var(--tail-them-y)) !important;
}

/* 我方尖角未领取 */
.bubble-me-custom:has(.msg-redpacket-card)::before {
  top: 18.5px !important;
  right: -6px !important;
  transform: translateY(-50%) translate(var(--tail-me-x), var(--tail-me-y)) !important;
}

/* 双方尖角已领取 */
:is(.bubble-me-custom, .bubble-them-custom):has(.msg-redpacket-card:is(.is-opened, [class*="receive" i], [class*="success" i]))::before {
  background: var(--redpacket-opened-bg) !important;
}

