.bubble-me-custom:has(.voice-transcription)::after {
  content: "" !important;
  display: block !important;
  width: 100% !important;
  height: 0 !important;
  line-height: 0 !important;
  font-size: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
