/* ==========================================================================
   11. 转账卡片与小尖角
   ========================================================================== */
:root {
  --transfer-card-width: 240px;
  --transfer-card-height: 88px;
  --transfer-card-radius: 4px;

  --transfer-card-bg: #ea8e39;

  --transfer-success-card-bg: #a57137;
  --transfer-success-color: #c09b70;

  --transfer-rejected-card-bg: #765128;
  --transfer-rejected-color: #9f8566;

  --transfer-expired-card-bg: #7d4f1e;
  --transfer-expired-color: #a48463;

  --transfer-tip-me: "你发起了一筆轉賬";
  --transfer-tip-them: "請收款";
  --transfer-tip-done: "已被接收";
  --transfer-tip-rejected: "已被退還";
  --transfer-tip-expired: "已過期";
}

/* 外层容器 */
.msg-bubble-container:has(.msg-transfer-card:not(.msg-redpacket-card)) {
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
  width: fit-content !important;
}

/* 卡片本体 */
.msg-transfer-card:not(.msg-redpacket-card) {
  width: var(--transfer-card-width) !important;
  height: var(--transfer-card-height) !important;
  box-sizing: border-box !important;
  border-radius: var(--transfer-card-radius) !important;
  position: relative !important;
  overflow: visible !important;
  border: none !important;
  background-color: var(--transfer-card-bg) !important;
}

/* 隐藏无关元素 */
.msg-transfer-card:not(.msg-redpacket-card),
.msg-transfer-card:not(.msg-redpacket-card) * {
  font-size: 0 !important;
  color: transparent !important;
  line-height: 0 !important;
  border: none !important;
  box-shadow: none !important;
}
.msg-transfer-card:not(.msg-redpacket-card) * {
  background: transparent !important;
}
.msg-transfer-card:not(.msg-redpacket-card) svg,
.msg-transfer-card:not(.msg-redpacket-card) hr,
.msg-transfer-card:not(.msg-redpacket-card) [class*="line" i] {
  display: none !important;
}

/* 待领取图标 */
.msg-transfer-card:not(.msg-redpacket-card)::before {
  content: "" !important;
  position: absolute !important;
  left: 14px !important;
  top: 16px !important;
  width: 38px !important;
  height: 38px !important;
  background-color: #ffffff !important;
  -webkit-mask: url("https://i.postimg.cc/cL8WdH7H/IMG-7321.png") no-repeat center / contain !important;
  mask: url("https://i.postimg.cc/cL8WdH7H/IMG-7321.png") no-repeat center / contain !important;
  z-index: 2 !important;
}

/* 底部文字 */
.msg-transfer-card:not(.msg-redpacket-card)::after {
  content: "轉賬" !important;
  position: absolute !important;
  left: 14px !important;
  bottom: 8px !important;
  font-size: 9.5px !important;
  color: rgba(255, 255, 255, 0.75) !important;
  line-height: 1 !important;
  font-family: -apple-system, sans-serif !important;
  z-index: 2 !important;
}

/* 金额与提示语 */
.msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-amount,
.msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-amount * {
  font-family: -apple-system, BlinkMacSystemFont, sans-serif !important;
  font-size: 15px !important;
  font-weight: 500 !important;
  line-height: 1.2 !important;
  color: #ffffff !important;
  visibility: visible !important;
}
.msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-amount {
  display: block !important;
  position: absolute !important;
  left: 64px !important;
  top: 16px !important;
  width: auto !important;
  z-index: 10 !important;
}
.msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-amount > *:first-child::after,
.msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-amount:not(:has(*))::before {
  content: ".00" !important;
  font-size: 15px !important;
  font-family: -apple-system, BlinkMacSystemFont, sans-serif !important;
  font-weight: 500 !important;
  color: inherit !important;
  visibility: visible !important;
}
.msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-amount::after {
  content: var(--transfer-tip-me) !important;
  display: block !important;
  font-size: 11.5px !important;
  font-weight: 400 !important;
  color: rgba(255, 255, 255, 0.85) !important;
  margin-top: 4px !important;
  line-height: 1.2 !important;
  white-space: nowrap !important;
  visibility: visible !important;
}
:is(.msg-them, .bubble-them-custom) .msg-transfer-card:not(.msg-redpacket-card) .msg-transfer-amount::after {
  content: var(--transfer-tip-them) !important;
}

/* 已接收 */
.msg-transfer-card.msg-transfer-success:not(.msg-redpacket-card),
.msg-transfer-card[class*="success" i]:not(.msg-redpacket-card),
.msg-transfer-card[class*="receive" i]:not(.msg-redpacket-card) {
  background-color: var(--transfer-success-card-bg) !important;
}
.msg-transfer-card.msg-transfer-success:not(.msg-redpacket-card)::before,
.msg-transfer-card[class*="success" i]:not(.msg-redpacket-card)::before,
.msg-transfer-card[class*="receive" i]:not(.msg-redpacket-card)::before {
  background-color: var(--transfer-success-color) !important;
  -webkit-mask: url("https://i.postimg.cc/NfnYhTXL/IMG-7322.png") no-repeat center / contain !important;
  mask: url("https://i.postimg.cc/NfnYhTXL/IMG-7322.png") no-repeat center / contain !important;
}
.msg-transfer-card.msg-transfer-success:not(.msg-redpacket-card) .msg-transfer-amount,
.msg-transfer-card.msg-transfer-success:not(.msg-redpacket-card) .msg-transfer-amount *,
.msg-transfer-card[class*="success" i]:not(.msg-redpacket-card) .msg-transfer-amount,
.msg-transfer-card[class*="success" i]:not(.msg-redpacket-card) .msg-transfer-amount *,
.msg-transfer-card[class*="receive" i]:not(.msg-redpacket-card) .msg-transfer-amount,
.msg-transfer-card[class*="receive" i]:not(.msg-redpacket-card) .msg-transfer-amount * {
  color: var(--transfer-success-color) !important;
}
.msg-transfer-card.msg-transfer-success:not(.msg-redpacket-card) .msg-transfer-amount::after,
.msg-transfer-card[class*="success" i]:not(.msg-redpacket-card) .msg-transfer-amount::after,
.msg-transfer-card[class*="receive" i]:not(.msg-redpacket-card) .msg-transfer-amount::after {
  content: var(--transfer-tip-done) !important;
  color: var(--transfer-success-color) !important;
}
.msg-transfer-card.msg-transfer-success:not(.msg-redpacket-card)::after,
.msg-transfer-card[class*="success" i]:not(.msg-redpacket-card)::after,
.msg-transfer-card[class*="receive" i]:not(.msg-redpacket-card)::after {
  color: var(--transfer-success-color) !important;
  opacity: 0.8 !important;
}

/* 已退还 */
.msg-transfer-card.msg-transfer-rejected:not(.msg-redpacket-card),
.msg-transfer-card[class*="reject" i]:not(.msg-redpacket-card) {
  background-color: var(--transfer-rejected-card-bg) !important;
}
.msg-transfer-card.msg-transfer-rejected:not(.msg-redpacket-card)::before,
.msg-transfer-card[class*="reject" i]:not(.msg-redpacket-card)::before {
  background-color: var(--transfer-rejected-color) !important;
  -webkit-mask: url("https://i.postimg.cc/pLcbZT9w/IMG-7532.png") no-repeat center / contain !important;
  mask: url("https://i.postimg.cc/pLcbZT9w/IMG-7532.png") no-repeat center / contain !important;
}
.msg-transfer-card.msg-transfer-rejected:not(.msg-redpacket-card) .msg-transfer-amount,
.msg-transfer-card.msg-transfer-rejected:not(.msg-redpacket-card) .msg-transfer-amount *,
.msg-transfer-card[class*="reject" i]:not(.msg-redpacket-card) .msg-transfer-amount,
.msg-transfer-card[class*="reject" i]:not(.msg-redpacket-card) .msg-transfer-amount * {
  color: var(--transfer-rejected-color) !important;
}
.msg-transfer-card.msg-transfer-rejected:not(.msg-redpacket-card) .msg-transfer-amount::after,
.msg-transfer-card[class*="reject" i]:not(.msg-redpacket-card) .msg-transfer-amount::after {
  content: var(--transfer-tip-rejected) !important;
  color: var(--transfer-rejected-color) !important;
}
.msg-transfer-card.msg-transfer-rejected:not(.msg-redpacket-card)::after,
.msg-transfer-card[class*="reject" i]:not(.msg-redpacket-card)::after {
  color: var(--transfer-rejected-color) !important;
  opacity: 0.8 !important;
}

/* 已过期 */
.msg-transfer-card.msg-transfer-expired-card:not(.msg-redpacket-card),
.msg-transfer-card[class*="expired" i]:not(.msg-redpacket-card) {
  background-color: var(--transfer-expired-card-bg) !important;
}
.msg-transfer-card.msg-transfer-expired-card:not(.msg-redpacket-card)::before,
.msg-transfer-card[class*="expired" i]:not(.msg-redpacket-card)::before {
  background-color: var(--transfer-expired-color) !important;
  -webkit-mask: url("https://i.postimg.cc/CLYpMBKx/IMG-9888.png") no-repeat center / contain !important;
  mask: url("https://i.postimg.cc/CLYpMBKx/IMG-9888.png") no-repeat center / contain !important;
}
.msg-transfer-card.msg-transfer-expired-card:not(.msg-redpacket-card) .msg-transfer-amount,
.msg-transfer-card.msg-transfer-expired-card:not(.msg-redpacket-card) .msg-transfer-amount *,
.msg-transfer-card[class*="expired" i]:not(.msg-redpacket-card) .msg-transfer-amount,
.msg-transfer-card[class*="expired" i]:not(.msg-redpacket-card) .msg-transfer-amount * {
  color: var(--transfer-expired-color) !important;
}
.msg-transfer-card.msg-transfer-expired-card:not(.msg-redpacket-card) .msg-transfer-amount::after,
.msg-transfer-card[class*="expired" i]:not(.msg-redpacket-card) .msg-transfer-amount::after {
  content: var(--transfer-tip-expired) !important;
  color: var(--transfer-expired-color) !important;
}
.msg-transfer-card.msg-transfer-expired-card:not(.msg-redpacket-card)::after,
.msg-transfer-card[class*="expired" i]:not(.msg-redpacket-card)::after {
  color: var(--transfer-expired-color) !important;
  opacity: 0.8 !important;
}

/* 转账尖角基底 */
.bubble-me-custom:has(.msg-transfer-card:not(.msg-redpacket-card))::before,
.bubble-them-custom:has(.msg-transfer-card:not(.msg-redpacket-card))::before {
  display: block !important;
  content: "" !important;
  width: var(--tail-width) !important;
  height: var(--tail-height) !important;
