  background: var(--transfer-card-bg) !important;
}

/* 对方尖角位置 */
.bubble-them-custom:has(.msg-transfer-card:not(.msg-redpacket-card))::before {
  top: 18.5px !important;
  left: -9px !important;
  transform: translateY(-50%) translate(var(--tail-them-x), var(--tail-them-y)) !important;
}

/* 我方尖角位置 */
.bubble-me-custom:has(.msg-transfer-card:not(.msg-redpacket-card))::before {
  top: 18.5px !important;
  right: -6px !important;
