}
.msg-them .voice-duration { margin-left: 8px !important; }
.msg-me .voice-duration { margin-right: 8px !important; }
.voice-duration::after {
  content: '"' !important;                     
  margin-left: 1.5px !important;
  font-size: 14px !important;
  font-weight: 600 !important;
  line-height: 1 !important;
}

/* ================== 「轉成文字」胶囊按钮 ================== */
.voice-transcription-toggle {
  position: relative !important;
  top: auto !important;
  left: auto !important;
  right: auto !important;
  bottom: auto !important;
  margin: 0 !important;

  /* 尺寸与自适应包裹 */
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  align-self: center !important;
  height: 22px !important;
  width: auto !important;
  min-width: 0 !important;
  max-width: none !important;
  flex: 0 0 auto !important;
  flex-shrink: 0 !important;
  box-sizing: border-box !important;
  padding: 0 8px !important;           
  border-radius: 11px !important;
  background: rgba(255, 255, 255, 0.1) !important;
  background-image: none !important;
  border: none !important;
  cursor: pointer !important;
  z-index: 10 !important;
  white-space: nowrap !important;
  outline: none !important;
  box-shadow: none !important;
  font-size: 0 !important;
  line-height: 0 !important;
  color: transparent !important;
  text-indent: -9999px !important;     
  overflow: visible !important;
}

/* 隐藏所有标签子元素 */
.voice-transcription-toggle * { 
  display: none !important; 
}
.voice-transcription-toggle::before {
  content: none !important;
  display: none !important;
}

/* 顺序控制 */
.msg-them .voice-transcription-toggle { order: 2 !important; }
.msg-me .voice-transcription-toggle   { order: 1 !important; }

.voice-transcription-toggle::after {
  content: "轉成文字" !important;
  display: block !important;
  font-size: 11px !important;
  color: #a8a8a8 !important;
  font-weight: 400 !important;
  line-height: 22px !important;
  text-indent: 0 !important;              
  margin: 0 !important;
  padding: 0 !important;
  letter-spacing: 0 !important;
}

/* ================== 换行断点与下方文字气泡 ================== */
.bubble-them-custom:has(.voice-transcription)::after,
.bubble-me-custom:has(.voice-transcription)::after {
  content: "" !important;
  display: block !important;
  width: 100% !important;
  height: 0 !important;
  line-height: 0 !important;
  font-size: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  order: 3 !important;                      
  pointer-events: none !important;
}

/* 转文字结果 */
.voice-transcription {
  order: 4 !important;                      
  flex-basis: auto !important;                 
  width: fit-content !important;               
  max-width: 100% !important;                 
  display: block !important;
  position: relative !important;
  margin-top: -5px !important;                
  margin-bottom: 2px !important;
  border-radius: 3px !important;
  padding: 5px 8px !important;
  font-size: 14px !important;
  line-height: 1.35 !important;
  background-color: #262626 !important;
  color: #dfdfdf !important;
  box-sizing: border-box !important;
  border: none !important;
  box-shadow: none !important;
  z-index: 1 !important;
  word-break: break-word !important;
}

.msg-them .voice-transcription { align-self: flex-start !important; }
.msg-me .voice-transcription   { align-self: flex-end !important; }

.voice-transcription::before,
.voice-transcription::after {
  display: none !important;
  content: none !important;
}

/* ===================================================================
   15. 时间戳 (夜间)
   =================================================================== */
.timestamp-custom,
.date-divider-custom,
.msg-time-separator,
.msg-date-separator {
    display: flex !important;
