/* ==========================================================================
   16. 文字图卡片
   ========================================================================== */
.msg-sim-card {
  position: relative !important;
  top: -9px !important;               
  display: block !important;
  width: 130px !important;            
  height: 186px !important;           
  padding: 0 !important;
  box-sizing: border-box !important;
  border-radius: 6px !important;
  border: none !important;
  overflow: visible !important;
  cursor: pointer !important;
  transform: none !important;
  background: transparent !important;
  box-shadow: none !important;
  margin-bottom: -17.5px !important; 
}

/* 消除外层包裹容器自带的内边距与背景，彻底贴合头像 */
:is([class*="bubble"], [class*="msg"]):has(.msg-sim-card) {
  padding-left: 0 !important;
  padding-right: 0 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

.msg-sim-card > * {
  display: none !important;
}

/* 底层图 */
.msg-sim-card > :first-child {
  display: block !important;
  position: absolute !important;
  top: 7px !important;                
  left: -22px !important;             
  width: 113px !important;            
  height: 154px !important;           
  border-radius: 6px !important;
  pointer-events: none !important;
  z-index: 0 !important;             
  font-size: 0 !important;
  line-height: 0 !important;
  color: transparent !important;
  opacity: 1 !important;
  visibility: visible !important;
  background-image: url("https://xiuxiu-pro-new.meitudata.com/posters/2670fdd1fa76ec2a3706d73960dfb544.jpeg") !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  background-color: transparent !important;
  transform: rotate(-7deg) !important;
  transform-origin: right center !important;
  box-shadow: none !important;
  -webkit-mask-image: -webkit-radial-gradient(white, black);
}

.msg-sim-card > :first-child * {
  display: none !important;
  opacity: 0 !important;
}

/* 中层图 */
.msg-sim-card::before {
  content: "" !important;
  position: absolute !important;
  top: 4px !important;                
  left: -11px !important;             
  width: 124px !important;            
  height: 170px !important;           
  border-radius: 6px !important;
  pointer-events: none !important;
  z-index: 1 !important;
  background-image: url("https://xiuxiu-pro-new.meitudata.com/posters/7e2365c4491733653c68a3e73725bf8b.jpeg") !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  transform: rotate(-3deg) !important;
  transform-origin: right center !important;
  box-shadow: none !important;
}

/* 顶层主图 */
.msg-sim-card::after {
  content: "" !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 130px !important;            
  height: 186px !important;           
  border-radius: 6px !important;
  pointer-events: none !important;
  z-index: 2 !important;
  background-image: url("https://xiuxiu-pro-new.meitudata.com/posters/c2f1737a3d4ca9236c0f88aa84ec65ba.jpeg") !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  transform: none !important;
  box-shadow: none !important;
}

/* 展开标签 */
.msg-sim-card > :nth-child(2) {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  position: absolute !important;
  top: 52% !important;                
  transform: translateY(-50%) !important;
  right: calc(100% + 27px) !important; 
  left: auto !important;
  padding: 2.5px 6.5px !important;   
  height: auto !important;
  width: auto !important;
  background: rgba(255, 255, 255, 0.16) !important;        
  border: 0.5px solid rgba(255, 255, 255, 0.12) !important;  
  border-radius: 8px !important;   
  font-size: 0 !important;
  line-height: 1 !important;
  white-space: nowrap !important;
  pointer-events: none !important;
  z-index: 3 !important;
  box-shadow: none !important;
}

.msg-sim-card > :nth-child(2)::before {
  content: "展开 3" !important;
  font-size: 9.5px !important;      
  color: #d1d1d6 !important;                                 
  letter-spacing: 0.3px !important;
  line-height: 1.1 !important;
  display: inline-block !important;
}

.msg-sim-card > :nth-child(2) * {
  display: none !important;
}

/* 对方气泡样式 */
:is(.bubble-them-custom, .msg-them) .msg-sim-card {
  left: 0 !important;
  margin-left: 0 !important;
  margin-right: auto !important;     
}

:is(.bubble-them-custom, .msg-them) .msg-sim-card > :first-child {
  left: auto !important;
  right: -22px !important;
  transform: rotate(7deg) !important;
  transform-origin: left center !important;
}

:is(.bubble-them-custom, .msg-them) .msg-sim-card::before {
  left: auto !important;
  right: -11px !important;
  transform: rotate(3deg) !important;
  transform-origin: left center !important;
}

