/* ---------- 气泡 + 头像 ---------- */
:root,
div.chat-detail-screen {
  /* 🐕 */ --wx-me-bg: #94ED6C;           /* 我方气泡 */
  /* 🐕 */ --wx-them-bg: #FFFFFF;         /* 对方气泡 */
  /* 🐕 */ --wx-bubble-text: #000000;     /* 气泡文字 */
  /* 🐕 */ --wx-bubble-radius: 4px;
  /* 🐕 */ --wx-font: 14.5px;             /* 气泡文字大小 */
  /* 🐕 */ --wx-avatar: 40px;             /* 头像大小，尖角跟着它居中 */
  /* 🐕 */ --wx-avatar-radius: 4px;       /* 头像圆角，微信是小圆角方形 */
  /* 🐕 */ --wx-tail: 8px;                /* 尖角方块边长，伸出去约 0.7 倍 */
  /* 🐕 */ --wx-tail-round: 1.3px;        /* 尖角尖端圆润程度 */
  /* 🐕 */ --wx-tail-nudge: 0px;          /* 尖角上下微调，正数往下 */
  /* 🐕 */ --wx-gap-same: 16px;            /* 同一个人连着发的气泡之间的距离，越小越近 */
  /* 🐕 */ --wx-gap-group: 22px;          /* 换人说话时，上一组最后一条和下一组之间的距离 */
  /* 🐕 */ --wx-quote-pull: 4px;          /* 上一条带引用框时，下一条再靠近多少，越大越近 */

  --bubble-me-color: #000000 !important;
  --bubble-them-color: #000000 !important;
}

/* ---------- 我方 / 对方分开的颜色（夜间两边不一样） ---------- */
:root,
div.chat-detail-screen {
  /* 🐕 */ --wx-me-text: #000000;         /* 我方气泡文字 */
  /* 🐕 */ --wx-them-text: #000000;       /* 对方气泡文字 */
  /* 🐕 */ --wx-tr-text: #000000;         /* 语音转文字的字 */
  --wx-voice-me-ink: #191919;
  --wx-voice-them-ink: #191919;
  --wx-voice-them-icon-c: var(--wx-voice-them-icon);
  --wxc-me-ink: #191919;
  --wxc-them-ink: #191919;
}

/* ---------- 气泡间距 + 语音 ---------- */
:root,
div.chat-detail-screen {
  /* 🐕 */ --wx-pad-y: 9.5px;             /* 气泡上下内边距：(头像 38 - 行高 21) / 2 */
