  /* 🐕 */ --wx-avatar-gap: 2px;         /* 气泡离头像再远多少，越大越远 */

  /* 🐕 */ --wx-voice-icon: 19px;         /* 声波图标大小 */
  /* 🐕 */ --wx-voice-gap: 6px;           /* 时长和图标的距离 */
  /* 🐕 */ --wx-voice-ink: #191919;       /* 时长文字颜色 */
