  /* 🐕 */ --voice-len-range: 140px;      /* 60 秒时最多再长多少 */
  /* 🐕 */ --wx-tr-gap: 5px;             /* 转文字气泡离语音条的距离 */
  /* 🐕 */ --wx-tr-me-bg: #FFFFFF;        /* 我方转文字气泡底色 */
  /* 🐕 */ --wx-tr-them-bg: #FFFFFF;      /* 对方转文字气泡底色 */
