@media (prefers-color-scheme: dark) {
  @supports not (-webkit-touch-callout: none) {
    body,
    body div.chat-detail-screen {
      --chat-bg-color: #111111;
      --wx-dim: rgba(17, 17, 17, 0.62);

      --wx-hdr-bg: rgba(23, 23, 23, 0.82);
      --wx-hdr-line: rgba(255, 255, 255, 0.08);
      --wx-ink: #D5D5D5;
      --wx-unread-bg: rgba(255, 255, 255, 0.12);
